import sys, json, re, subprocess, importlib.util
sys.path.insert(0, '/tmp/vdirstub')
OUT='/home/tirandagan.guest/naive-arm/output'
def load(p, n):
    s=importlib.util.spec_from_file_location(n,p); m=importlib.util.module_from_spec(s); s.loader.exec_module(m); return m
syn = load(OUT+'/vdir.py','vdir').vdir_syntax_spec
assert len(syn)==1 and len(syn[0])==2
opts, pos = syn[0]
assert len(pos)==1 and pos[0].kind=='Path' and not pos[0].dash
syn_flags=set(); syn_opts={}
for n in opts:
    names=[n.flag]+n.alias
    if n.kind=='Flag': syn_flags.update(names)
    else:
        for x in names: syn_opts[x]=n
tab=json.load(open(OUT+'/annotation/vdir.json'))
js_flags=set(); js_opts={}
for e in tab['flag']: js_flags.update([e] if isinstance(e,str) else e)
for e in tab['option']:
    for x in e[:-1]: js_opts[x]=e[-1]
# options from --help
help_=subprocess.run(['/usr/bin/vdir','--help'],capture_output=True,text=True).stdout
help_flags=set(); help_opts=set()
for line in help_.splitlines():
    m=re.match(r'\s+((?:-\S+,\s+)*-\S+)\s{2,}',line) or re.match(r'\s+((?:-\S+,\s+)*-\S+)\s*$',line)
    if not m: continue
    for tok in re.split(r',\s+',m.group(1)):
        if '[=' in tok: name=tok.split('[=')[0]; help_flags.add(name); help_opts.add(name)
        elif '=' in tok: help_opts.add(tok.split('=')[0])
        else: help_flags.add(tok)
help_flags.discard('-p'); help_opts.discard('--indicator-style'); help_flags.add('-p'); help_opts.add('--indicator-style')  # "-p, --indicator-style=slash" line
help_opts.add('-T'); help_opts.add('-w'); help_opts.add('-I')  # short forms share the long's arg
print('help flags not in syntax:', help_flags-syn_flags)
print('syntax flags not in help:', syn_flags-help_flags)
print('help opts not in syntax:', help_opts-set(syn_opts))
print('syntax opts not in help:', set(syn_opts)-help_opts)
# json: optional-arg ones are flags only
json_expected_opts = help_opts - {'--color','--classify','--hyperlink'}
print('json flags vs help:', help_flags ^ js_flags)
print('json opts vs help:', json_expected_opts ^ set(js_opts))
# run every option through the binary
import os, tempfile
d=tempfile.mkdtemp(); open(d+'/a','w').close()
samples={'Size':'1K','Glob':'z*','Selection':None,'TimeStyle':'iso','Integer':'4'}
bad=[]
def run(args):
    r=subprocess.run(['/usr/bin/vdir']+args,cwd=d,capture_output=True,text=True)
    return r.returncode, r.stderr
for f in sorted(syn_flags):
    if f in ('--help','--version'): continue
    rc,err=run([f,'a'])
    if rc!=0: bad.append((f,err.strip()))
for name,n in sorted(syn_opts.items()):
    vals = list(n.choices) if n.choices else [samples[n.kind]]
    for v in vals:
        for form in ([name+'='+v] if n.eq else []) + ([name,v] if not n.eq or name.startswith('-') and not name.startswith('--') else []):
            pass
        forms=[[name+'='+v]] if name.startswith('--') else [[name,v],[name+v]]
        for args in forms:
            rc,err=run(args+['a'])
            if rc!=0: bad.append((args,err.strip()))
# negative: json flags must not consume next word
for f in ['--color','-F','--classify','--hyperlink','-p']:
    rc,err=run([f,'a']); 
    if rc!=0: bad.append((f+' then operand',err))
print('binary rejections:', bad)
# IO / parallel classes
io=load(OUT+'/annotation/InputOutputInfoGeneratorVdir.py','io').InputOutputInfoGeneratorVdir([],[]); io.generate_info(); print('io calls:', io.calls)
pa=load(OUT+'/annotation/ParallelizabilityInfoGeneratorVdir.py','pa').ParallelizabilityInfoGeneratorVdir(); pa.generate_info(); print('par calls:', pa.calls)
EOF
